<div class="row g-3 mb-4"><div class="col-md-4"><label class="form-label">Client</label><select class="form-select" name="customer_id"><option value="">Vente comptoir</option>@foreach($customers as $customer)<option value="{{ $customer->id }}" @selected(old('customer_id')==$customer->id)>{{ $customer->name }}</option>@endforeach</select></div><div class="col-md-4"><label class="form-label">Date *</label><input class="form-control" type="date" name="sold_at" required value="{{ old('sold_at',now()->toDateString()) }}"></div><div class="col-md-4"><label class="form-label">Mode de paiement</label><select class="form-select" name="payment_method"><option value="">Non renseigné</option><option value="cash">Espèces</option><option value="card">Carte</option><option value="transfer">Virement</option><option value="mobile_money">Mobile money</option><option value="other">Autre</option></select></div></div>
<div class="d-flex justify-content-between align-items-center mb-2"><h2 class="h6 fw-bold mb-0">Produits vendus</h2><button type="button" class="btn btn-sm btn-outline-primary" @click="add()"><i class="bi bi-plus-lg me-1"></i>Ajouter une ligne</button></div>
<div class="table-responsive"><table class="table align-middle"><thead><tr><th style="min-width:260px">Produit</th><th>Disponible</th><th style="width:160px">Quantité</th><th>Prix unitaire</th><th>Total ligne</th><th></th></tr></thead><tbody><template x-for="(item,index) in items" :key="item.key"><tr><td><select class="form-select" :name="`items[${index}][product_id]`" x-model="item.product_id" required><option value="">Sélectionner…</option><template x-for="product in products" :key="product.id"><option :value="product.id" x-text="product.name + ' · ' + product.sku"></option></template></select></td><td><span x-text="selected(item)?.stock ?? '—'"></span> <span class="small muted" x-text="selected(item)?.unit ?? ''"></span></td><td><input class="form-control" type="number" min="1" step="1" :name="`items[${index}][quantity]`" x-model="item.quantity" required></td><td><span x-text="selected(item) ? format(selected(item).price) + ' {{ $currency ?? 'FCFA' }}' : '—'"></span></td><td class="fw-semibold" x-text="format(lineTotal(item)) + ' {{ $currency ?? 'FCFA' }}'"></td><td><button type="button" class="btn btn-sm btn-light text-danger" @click="remove(index)" :disabled="items.length===1" aria-label="Retirer la ligne"><i class="bi bi-trash"></i></button></td></tr></template></tbody></table></div>
<div class="d-flex justify-content-end mb-3"><div class="panel px-4 py-3 text-end" style="min-width:260px"><div class="small muted">Sous-total des produits</div><div class="fw-semibold" x-text="format(subtotal()) + ' {{ $currency ?? 'FCFA' }}'"></div><div class="small muted mt-2">Total après remise</div><div class="h4 fw-bold mb-0 text-primary" x-text="format(total()) + ' {{ $currency ?? 'FCFA' }}'"></div></div></div>
