@push('scripts')<script>function saleBuilder(products, rows, discount){return {products,items:rows.map((r,i)=>({...r,key:i})),discount:Number(discount)||0,nextKey:rows.length,selected(item){return this.products.find(p=>String(p.id)===String(item.product_id))},lineTotal(item){const product=this.selected(item);const quantity=Number(item.quantity)||0;return product&&quantity>0?Number(product.price)*quantity:0},subtotal(){return this.items.reduce((sum,item)=>sum+this.lineTotal(item),0)},total(){return Math.max(0,this.subtotal()-(Number(this.discount)||0))},format(amount){return Number(amount||0).toLocaleString('fr-FR',{maximumFractionDigits:2})},add(){this.items.push({key:this.nextKey++,product_id:'',quantity:'1'})},remove(index){if(this.items.length>1)this.items.splice(index,1)}}}</script>@endpush
@endsection
